import limited_client as robot,numpy as np
o=robot.observe('corner4'); a=o['rgb'];
for roi in [(160,210,220,250),(165,205,230,255),(175,215,215,250)]:
 x0,y0,x1,y1=roi; p=a[y0:y1,x0:x1]; m=(p[:,:,0]>100)&(p[:,:,0]>p[:,:,1]*1.6)&(p[:,:,0]>p[:,:,2]*1.4)
 yy,xx=np.where(m); print(roi,'n',len(xx),'bbox', (xx.min()+x0,yy.min()+y0,xx.max()+x0,yy.max()+y0) if len(xx) else None)
 if len(xx):
  u=int(xx.mean()+x0);v=int(yy.mean()+y0); z=o['depth_m'][v,u]; q=np.linalg.inv(o['intrinsic'])@np.array([u,v,1])*z; print('mean',u,v,'d',z,'world',(o['camera_to_world']@np.r_[q,1])[:3])
